// @vegastack review-split-01@0.23.43 sha256-Cc5/hxHD8Uf2kZyKL0fvtCPMG2g7yQdFbR6UiiYNPaE=

"use client";

import * as React from "react";

import {
  AudioPlayer,
  type AudioPlayerActions,
} from "@/components/ui/audio-player";
import { Checkbox } from "@/components/ui/checkbox";
import { useContainerWidth } from "@/components/ui/data-table-parts";
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldLabel,
} from "@/components/ui/field";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Transcript,
  TranscriptList,
  TranscriptSearch,
  type TranscriptSegment,
} from "@/components/ui/transcript";
import { cn } from "@vegastack/design";

import type { ActionItem } from "./sample-meeting";

/** Props for {@link ReviewSplit}. */
export interface ReviewSplitProps {
  /** The summary, one paragraph per point. */
  summary: string[];
  /** The action items; their checked state is the block's own until you wire it. */
  actionItems: ActionItem[];
  /** The transcript segments. */
  segments: TranscriptSegment[];
  /** Speaker id → display name. */
  speakers: Record<string, string>;
  /** The recording's URL, or a function that resolves it on first play. */
  recordingSrc: string | (() => Promise<string>);
  /**
   * The record is still loading: each panel shows a skeleton in its own proportions.
   * @default false
   */
  loading?: boolean;
}

type PanelId = "summary" | "actions" | "transcript";

/** The width (in rem) at which the split turns into tabs — the `@4xl` container size. */
const SPLIT_AT_REM = 56;

function rootFontSize(): number {
  if (typeof window === "undefined") return 16;
  return parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
}

/**
 * A review page's two panes from ONE measure. The block measures its own container
 * (`useContainerWidth`) and its layout classes use the same `@4xl/review` container query, so the
 * layout (grid or single column) and the mode (side by side or tabs) switch together — whether the
 * window resized or the sidebar opened. Before the first measurement it assumes narrow, the
 * server-rendered answer.
 *
 * Wide: summary and action items on the left with the docked player at the end of the column —
 * one flex column, so the player sticks to the viewport's bottom edge while the column scrolls —
 * and the transcript in a sticky right pane that scrolls on its own. Narrow: `Tabs` over the SAME
 * three panels. Each panel mounts once and only its tab semantics change, so a checked action item
 * or a transcript search survives a switch.
 *
 * @example
 * <ReviewSplit
 *   summary={SUMMARY}
 *   actionItems={ACTION_ITEMS}
 *   segments={SEGMENTS}
 *   speakers={SPEAKERS}
 *   recordingSrc="/recordings/weekly-sync.mp3"
 * />
 */
export function ReviewSplit({
  summary,
  actionItems,
  segments,
  speakers,
  recordingSrc,
  loading = false,
}: ReviewSplitProps) {
  const [measureRef, width] = useContainerWidth();
  const narrow = width === null || width < SPLIT_AT_REM * rootFontSize();
  const [tab, setTab] = React.useState<PanelId>("summary");
  const [done, setDone] = React.useState<Record<string, boolean>>(() =>
    Object.fromEntries(actionItems.map((item) => [item.id, item.done])),
  );
  const [time, setTime] = React.useState(0);
  const player = React.useRef<AudioPlayerActions>(null);
  const [media, setMedia] = React.useState<HTMLAudioElement | null>(null);

  React.useEffect(() => {
    if (!media) return;
    const update = () => setTime(media.currentTime);
    media.addEventListener("timeupdate", update);
    return () => media.removeEventListener("timeupdate", update);
  }, [media]);

  const openCount = actionItems.filter((item) => !done[item.id]).length;

  // In wide mode a panel is a plain region: no tab role, never hidden or inert. The SAME element renders in
  // both modes (only these props change), so nothing inside it remounts on a switch.
  const panelProps = (id: PanelId) =>
    narrow
      ? { "data-slot": "review-split-panel", "data-panel": id }
      : {
          "data-slot": "review-split-panel",
          "data-panel": id,
          role: undefined,
          hidden: false,
          inert: undefined,
          "data-hidden": undefined,
          tabIndex: undefined,
          "aria-labelledby": undefined,
        };

  return (
    <div
      ref={measureRef}
      data-slot="review-split"
      data-mode={narrow ? "narrow" : "wide"}
      className="@container/review min-w-0 [--review-split-offset:4rem]"
    >
      <Tabs
        value={tab}
        onValueChange={(value) => setTab(value as PanelId)}
        className="grid min-w-0 gap-6 @4xl/review:grid-cols-[minmax(0,1.55fr)_minmax(0,1fr)] @4xl/review:items-start"
      >
        {narrow ? (
          <TabsList variant="line" aria-label="Meeting">
            <TabsTrigger value="summary">Summary</TabsTrigger>
            <TabsTrigger value="actions">
              Action items{" "}
              <span
                aria-hidden="true"
                className="text-muted-foreground tabular-nums"
              >
                {openCount}
              </span>
              <span className="sr-only">{openCount} open</span>
            </TabsTrigger>
            <TabsTrigger value="transcript">Transcript</TabsTrigger>
          </TabsList>
        ) : null}

        {/* The left column is ONE element in wide mode, so the docked player's `sticky bottom-0` has
            the whole column to stick within; narrow, it is `contents` and its panels are the tab grid's
            own rows. */}
        <div
          data-slot="review-split-column"
          className="contents @4xl/review:col-start-1 @4xl/review:row-start-1 @4xl/review:flex @4xl/review:min-w-0 @4xl/review:flex-col @4xl/review:gap-6"
        >
          <TabsContent
            value="summary"
            keepMounted
            className="flex flex-col gap-3"
            {...panelProps("summary")}
          >
            <h2 className="font-heading text-base font-medium">Summary</h2>
            {loading ? (
              <div className="flex flex-col gap-2" aria-hidden>
                <Skeleton className="h-4 w-full" />
                <Skeleton className="h-4 w-11/12" />
                <Skeleton className="h-4 w-3/4" />
              </div>
            ) : (
              summary.map((point) => (
                <p key={point} className="text-sm leading-relaxed">
                  {point}
                </p>
              ))
            )}
          </TabsContent>

          <TabsContent
            value="actions"
            keepMounted
            className="flex flex-col gap-3"
            {...panelProps("actions")}
          >
            <h2 className="font-heading text-base font-medium">
              Action items{" "}
              <span className="font-sans text-muted-foreground tabular-nums">
                {openCount} open
              </span>
            </h2>
            {loading ? (
              <div className="flex flex-col gap-3" aria-hidden>
                {actionItems.map((item) => (
                  <Skeleton key={item.id} className="h-5 w-2/3" />
                ))}
              </div>
            ) : (
              <ul className="flex flex-col gap-3">
                {actionItems.map((item) => (
                  <li key={item.id}>
                    <Field orientation="horizontal">
                      <Checkbox
                        checked={done[item.id] ?? false}
                        onCheckedChange={(checked) =>
                          setDone((current) => ({
                            ...current,
                            [item.id]: checked === true,
                          }))
                        }
                      />
                      <FieldContent>
                        <FieldLabel className="font-normal">
                          {item.text}
                        </FieldLabel>
                        <FieldDescription>{item.owner}</FieldDescription>
                      </FieldContent>
                    </Field>
                  </li>
                ))}
              </ul>
            )}
          </TabsContent>

          {/* Narrow, the player still closes the page, after whichever panel is showing. */}
          <AudioPlayer
            docked
            label="Meeting recording"
            src={recordingSrc}
            mediaRef={setMedia}
            actionsRef={player}
            className="order-last min-w-0 @4xl/review:order-none"
          />
        </div>

        <TabsContent
          value="transcript"
          keepMounted
          className={cn(
            "flex min-h-0 flex-col gap-3",
            "@4xl/review:sticky @4xl/review:top-(--review-split-offset) @4xl/review:col-start-2 @4xl/review:row-start-1 @4xl/review:max-h-[calc(100dvh-var(--review-split-offset))]",
          )}
          {...panelProps("transcript")}
        >
          <h2 className="font-heading text-base font-medium">Transcript</h2>
          <Transcript
            aria-label="Transcript"
            segments={segments}
            speakerName={(id) => speakers[id] ?? id}
            currentTime={time}
            onSeek={(seconds) => player.current?.seek(seconds, { play: true })}
            loading={loading}
            className="h-[60dvh] min-h-0 rounded-lg border border-border @4xl/review:h-auto @4xl/review:flex-1"
          >
            <TranscriptSearch />
            <TranscriptList />
          </Transcript>
        </TabsContent>
      </Tabs>
    </div>
  );
}

// @vegastack review-split-01@0.23.43 sha256-Cc5/hxHD8Uf2kZyKL0fvtCPMG2g7yQdFbR6UiiYNPaE=

/**
 * Sample data for `review-split-01`: one meeting's summary, action items and transcript. Replace it
 * with your own record; the shapes are the ones `ReviewSplit` reads.
 */

import type { TranscriptSegment } from "@/components/ui/transcript";

/** One action item from the meeting. */
export interface ActionItem {
  id: string;
  text: string;
  owner: string;
  done: boolean;
}

/** People who spoke, by speaker id. */
export const SPEAKERS: Record<string, string> = {
  ana: "Ana Ruiz",
  raj: "Raj Patel",
  mei: "Mei Chen",
};

/** The meeting's summary, one paragraph per point. */
export const SUMMARY: string[] = [
  "Marketing came in under plan because two events moved online, and online registrations were up by about a third.",
  "The team agreed to keep one event online next quarter, once the regional teams have weighed in.",
  "Support has two open roles; the first interviews are next week, and the event savings cover both offers.",
];

/** What the meeting agreed someone would do. */
export const ACTION_ITEMS: ActionItem[] = [
  {
    id: "a1",
    text: "Send the regional teams the event numbers",
    owner: "Raj Patel",
    done: false,
  },
  {
    id: "a2",
    text: "Collect regional answers by Friday",
    owner: "Raj Patel",
    done: false,
  },
  {
    id: "a3",
    text: "Confirm the support hiring budget with finance",
    owner: "Raj Patel",
    done: true,
  },
  {
    id: "a4",
    text: "Schedule the first support interviews",
    owner: "Mei Chen",
    done: false,
  },
];

const LINES: Array<[string, string]> = [
  ["ana", "Thanks for joining. Let’s start with the quarterly budget review."],
  [
    "raj",
    "Marketing came in under plan, mostly because two events moved online.",
  ],
  ["mei", "Did the online events reach the same number of people?"],
  ["raj", "More, actually. Registrations were up by about a third."],
  ["ana", "Then we should keep one of them online next quarter as well."],
  ["mei", "Agreed. I’d like the regional teams to weigh in before we decide."],
  ["raj", "I can send them the numbers today and collect answers by Friday."],
  ["ana", "Good. Next item: the hiring plan for the support team."],
  ["mei", "We have two open roles, and the first interviews are next week."],
  ["ana", "Let’s make sure the budget covers both before we make offers."],
  ["raj", "It does, with the savings from events. I’ll confirm with finance."],
  ["ana", "Great. That’s everything on the list. Thanks, everyone."],
];

/** The transcript, about seven seconds a line. */
export const SEGMENTS: TranscriptSegment[] = LINES.map(
  ([speaker, text], index) => ({
    id: `line-${index + 1}`,
    start: index * 7.5,
    speaker,
    text,
  }),
);

/** Where the recording is served from. */
export const RECORDING_SRC = "/recordings/weekly-sync.mp3";

// @vegastack review-split-01@0.23.43 sha256-Cc5/hxHD8Uf2kZyKL0fvtCPMG2g7yQdFbR6UiiYNPaE=

import { AppShellPage } from "@/components/ui/app-shell";
import { PageHeader } from "@/components/ui/page-header";

import { ReviewSplit } from "./components/review-split";
import {
  ACTION_ITEMS,
  RECORDING_SRC,
  SEGMENTS,
  SPEAKERS,
  SUMMARY,
} from "./components/sample-meeting";

/**
 * `review-split-01` — a record's review page: a `PageHeader` h1 over `ReviewSplit`, the two-pane
 * summary + transcript layout that turns into tabs when its own container is narrow. It fills the
 * content region (`AppShellPage size="full"`).
 *
 * Replace the sample meeting with your record and `RECORDING_SRC` with its recording.
 *
 * @example
 * // app/meetings/[id]/page.tsx, straight after `shadcn add @vegastack/review-split-01`
 * export { default } from "./page";
 */
export default function Page() {
  return (
    <AppShellPage size="full">
      <PageHeader
        title="Weekly sync with Skyline"
        description="Tuesday 3 September · 34 minutes · Ana Ruiz, Raj Patel, Mei Chen"
      />
      <ReviewSplit
        summary={SUMMARY}
        actionItems={ACTION_ITEMS}
        segments={SEGMENTS}
        speakers={SPEAKERS}
        recordingSrc={RECORDING_SRC}
      />
    </AppShellPage>
  );
}
